(() => {
  const assert = (condition, message) => { if (!condition) throw new Error(`DEXTRA label regression: ${message}`); };
  assert(document.querySelector('#scene-frame').clientWidth >= 500, 'run this fixture at desktop width (1440 recommended)');
  const visible = element => {
    for (let node = element; node instanceof Element; node = node.parentElement) {
      const style = getComputedStyle(node);
      if (node.hidden || style.display === 'none' || style.visibility === 'hidden' || style.visibility === 'collapse' || Number(style.opacity) === 0) return false;
    }
    return true;
  };
  const check = (context, expected = []) => {
    const labels = [...document.querySelectorAll('#callouts .callout')].filter(visible);
    const paths = [...document.querySelectorAll('#leader-lines path')].filter(visible);
    const circles = [...document.querySelectorAll('#leader-lines circle')].filter(visible);
    const names = labels.map(element => element.textContent.trim());
    assert(labels.length === paths.length && paths.length === circles.length, `${context}: ${labels.length} labels / ${paths.length} paths / ${circles.length} anchor dots`);
    for (const name of expected) assert(names.includes(name), `${context}: missing ${name}; visible: ${names.join(', ')}`);
    for (const label of labels) {
      const part = label.dataset.part;
      assert(Boolean(part), `${context}: callout lacks semantic part identifier`);
      const groups = [...document.querySelectorAll('#leader-lines g[data-part]')].filter(group => visible(group) && group.dataset.part === part);
      assert(groups.length === 1, `${context}: ${part} must have exactly one matching connector group`);
      assert(groups[0].querySelectorAll('path').length === 1 && groups[0].querySelectorAll('circle').length === 1, `${context}: ${part} connector must contain one path and one anchor dot`);
      const path = groups[0].querySelector('path');
      const circle = groups[0].querySelector('circle');
      assert(visible(path) && visible(circle), `${context}: ${part} connector is hidden while its label is visible`);
      const endpoint = path.getPointAtLength(path.getTotalLength());
      assert(Math.hypot(Number(circle.getAttribute('cx')) - endpoint.x, Number(circle.getAttribute('cy')) - endpoint.y) < .1, `${context}: ${part} leader and anchor dot do not meet`);
      const rect = label.getBoundingClientRect();
      assert([rect.x, rect.y, rect.width, rect.height].every(Number.isFinite) && rect.width > 0 && rect.height > 0, `${context}: invalid label bounds`);
    }
    const anchors = circles.map(circle => {
      const values = ['cx', 'cy', 'r'].map(name => Number(circle.getAttribute(name)));
      assert(values.every(Number.isFinite) && values[2] > 0, `${context}: invalid anchor-dot geometry`);
      return values;
    });
    for (const path of paths) {
      const data = path.getAttribute('d') || '';
      const values = (data.match(/[-+]?(?:\d*\.\d+|\d+\.?\d*)(?:e[-+]?\d+)?/gi) || []).map(Number);
      assert(data.length > 0 && !/NaN|Infinity|undefined/.test(data) && values.length >= 4 && values.every(Number.isFinite), `${context}: invalid leader path ${data}`);
      assert(Number.isFinite(path.getTotalLength()) && path.getTotalLength() > 0, `${context}: empty leader path`);
      const endpoint = path.getPointAtLength(path.getTotalLength());
      assert(anchors.some(([x, y]) => Math.hypot(x - endpoint.x, y - endpoint.y) < .1), `${context}: leader has no matching anchor dot`);
    }
    return names;
  };
  window.__dextraLabelRegression = {assert, check, expected: ['Articulated fingers', 'Opposing thumb', 'Wrist interface']};
  window.__dextra.seek(0);
  return {ready: true, labels: check('initial view', window.__dextraLabelRegression.expected)};
})()

(() => {
  const {check, expected} = window.__dextraLabelRegression;
  let samples = 0;
  for (const direction of [1, -1]) {
    for (let step = 0; step <= 200; step++) {
      const grip = direction === 1 ? step / 200 : 1 - step / 200;
      window.__dextra.setPose({grip, separation: 0});
      check(`${direction === 1 ? 'closing' : 'opening'} grip=${grip.toFixed(3)}`, expected);
      samples++;
    }
  }
  return {passed: 'dense forward and reverse closure', samples};
})()

(async () => {
  const {assert,check,expected}=window.__dextraLabelRegression;
  window.__dextra.seek(4);
  const initial=new Map([...document.querySelectorAll('#callouts .callout')].map(label=>[label.dataset.part,{label,left:label.style.left,top:label.style.top}]));
  const speed=document.querySelector('#speed');speed.value='2';speed.dispatchEvent(new Event('change'));
  document.querySelector('#play').click();
  let frames=0,previous=performance.now(),total=0;
  return await new Promise((resolve,reject)=>{
    const deadline=performance.now()+30000;
    function sample(now){
      try{
        assert(now<deadline,'timed playback did not finish closure and release');
        if(window.__dextra.stats().time>=18){
          window.__dextra.pause();
          speed.value='1';speed.dispatchEvent(new Event('change'));
          assert(frames>30,'too few rendered frames to verify timed playback');
          resolve({passed:'timed closure, hold, and release without disappearing or jumping labels',frames,meanFrameMs:Math.round(total/frames)});return;
        }
        check('timed playback',expected);
        for(const label of document.querySelectorAll('#callouts .callout')){
          const prior=initial.get(label.dataset.part);
          assert(prior?.label===label,'callout was removed and recreated during playback');
          assert(label.style.left===prior.left&&label.style.top===prior.top,'callout changed its screen slot during playback');
        }
        total+=now-previous;previous=now;frames++;
        requestAnimationFrame(sample);
      }catch(error){window.__dextra.pause();reject(error);}
    }
    requestAnimationFrame(sample);
  });
})()

(() => {
  const {assert, check} = window.__dextraLabelRegression;
  window.__dextra.setPose({grip: 0, separation: 0});
  window.__dextra.select('actuators');
  const names = check('assembled palm view');
  assert(!names.includes('Actuator bank'), 'covered actuators must remain occluded even when selected');
  assert(!names.includes('Dorsal carapace'), 'back shell must remain occluded from the assembled palm view');
  return {passed: 'meaningful occlusion', labels: names};
})()

(() => {
  const {check} = window.__dextraLabelRegression;
  return {passed: 'exposed actuator positive control', labels: check('separated back view', ['Actuator bank'])};
})()

(() => {
  const {assert, check, expected} = window.__dextraLabelRegression;
  window.__dextra.seek(0);
  const control = document.querySelector('#show-labels');
  assert(control.checked, 'labels should start enabled');
  control.click();
  assert(!control.checked, 'label toggle did not disable');
  assert(check('labels disabled').length === 0, 'disabled labels and connectors must all be hidden');
  control.click();
  assert(control.checked, 'label toggle did not enable');
  return {passed: 'labels and connectors toggle together', labels: check('labels restored', expected)};
})()
